// Anti-pattern: caching data that is already fast
public async Task<Product> GetProductAsync(Guid id)
{
    // IMemoryCache adds overhead for every request,
    // even cache misses.
    return await _cache.GetOrCreateAsync(id, async entry =>
    {
        entry.AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5);
        return await _dbContext.Products.FindAsync(id);
    });
}

// Better approach: measure first, then decide
public async Task<Product> GetProductAsync(Guid id)
{
    // Direct query. If this is slow, optimize the query
    // or add an index before adding a cache.
    return await _dbContext.Products.FindAsync(id);
}
